import React from 'react';
import { useAuth } from '../context/AuthContext';
import { dashboardAPI } from '../services/api';
import useFetch from '../hooks/useFetch';
import { timeAgo, emotionIcon, getAdherenceColor } from '../utils/helpers';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer, BarChart, Bar } from 'recharts';
import './DashboardPage.css';

export default function DashboardPage() {
  const { user } = useAuth();
  if (user?.role === 'caregiver') return <CaregiverDashboard data={d} user={user} />;
if (user?.role === 'doctor')    return <DoctorDashboard    data={d} user={user} />;
if (user?.role === 'family')    return <FamilyDashboard    data={d} user={user} />;
  return <PatientDash />;
}

/* ── Patient Dashboard ───────────────────────────────────────── */
function PatientDash() {
  const { data, loading } = useFetch(() => {
  if (user?.role === 'family')    return dashboardAPI.getFamily();
  if (user?.role === 'patient')   return dashboardAPI.getMe();
  if (user?.role === 'caregiver') return dashboardAPI.getCaregiver();
  if (user?.role === 'doctor')    return dashboardAPI.getDoctor();
  return dashboardAPI.getMe();
}, [user?.role]);
  const d = data?.dashboard;

  if (loading) return <div className="page-loader"><div className="spinner" /><span>Loading your dashboard…</span></div>;

  const doses   = d?.medications?.todaySummary || {};
  const emotion = d?.emotions?.latestFace;
  const sent    = d?.emotions?.sentimentLast7Days || {};

  const chartData = Object.entries(sent).map(([k,v]) => ({ name: k, value: v }));

  return (
    <div className="dash anim-fade-up">
      <div className="page-header">
        <div className="page-header__left">
          <h1>Good {greeting()}, {d?.patient?.name?.split(' ')[0] || 'there'}</h1>
          <p>Here's your health summary for today</p>
        </div>
      </div>

      <div className="dash-stats">
        <div className="stat-card">
          <span className="stat-label">Doses today</span>
          <span className="stat-value">{doses.taken || 0}<span style={{fontSize:18,color:'var(--ink-muted)'}}>/{doses.total || 0}</span></span>
          <span className="stat-sub">{doses.missed ? `${doses.missed} missed` : 'All on track'}</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Active medications</span>
          <span className="stat-value">{d?.medications?.activeCount || 0}</span>
          <span className="stat-sub">Current prescriptions</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Open alerts</span>
          <span className="stat-value" style={{color: d?.alerts?.openCount > 0 ? 'var(--danger)' : 'inherit'}}>{d?.alerts?.openCount || 0}</span>
          <span className="stat-sub">{d?.alerts?.openCount > 0 ? 'Needs attention' : 'All clear'}</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Current mood</span>
          <span className="stat-value" style={{fontSize:36}}>{emotion ? emotionIcon(emotion.emotion) : '—'}</span>
          <span className="stat-sub">{emotion ? emotion.emotion : 'No reading yet'}</span>
        </div>
      </div>

      <div className="dash-grid">
        <div className="card">
          <h3 className="card-title">Sentiment this week</h3>
          <ResponsiveContainer width="100%" height={180}>
            <BarChart data={chartData} barSize={32}>
              <XAxis dataKey="name" tick={{fontSize:12}} axisLine={false} tickLine={false}/>
              <YAxis hide />
              <Tooltip contentStyle={{borderRadius:8,border:'none',boxShadow:'0 4px 16px rgba(0,0,0,0.1)',fontSize:13}} />
              <Bar dataKey="value" radius={[6,6,0,0]}
                fill="var(--sage)" />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="card">
          <h3 className="card-title">Today's schedule</h3>
          <div className="med-list">
            {d?.medications?.todaySummary?.total > 0 ? (
              d.medications.adherence30d?.map((m, i) => (
                <div key={i} className="med-row">
                  <div className="med-row__dot" style={{background: getAdherenceColor(m.adherenceRate)}} />
                  <span className="med-row__name">{m.name}</span>
                  <span className="med-row__rate" style={{color: getAdherenceColor(m.adherenceRate)}}>
                    {m.adherenceRate !== null ? `${m.adherenceRate}%` : '—'}
                  </span>
                </div>
              ))
            ) : (
              <div className="empty-state" style={{padding:'20px 0'}}>
                <p>No medications scheduled</p>
              </div>
            )}
          </div>
        </div>

        <div className="card">
          <h3 className="card-title">Recent alerts</h3>
          {d?.alerts?.recent?.length > 0 ? (
            <div className="alert-list">
              {d.alerts.recent.map(a => (
                <div key={a._id} className={`alert-item alert-item--${a.severity}`}>
                  <div className="alert-item__dot" />
                  <div>
                    <p className="alert-item__title">{a.title}</p>
                    <p className="alert-item__time">{timeAgo(a.createdAt)}</p>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="empty-state" style={{padding:'20px 0'}}>
              <p>No open alerts</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ── Caregiver Dashboard ─────────────────────────────────────── */
function CaregiverDash() {
  const { data, loading } = useFetch(() => dashboardAPI.getCaregiver(), []);
  if (loading) return <div className="page-loader"><div className="spinner" /></div>;

  const patients = data?.patients || [];

  return (
    <div className="dash anim-fade-up">
      <div className="page-header">
        <div className="page-header__left">
          <h1>Care overview</h1>
          <p>Monitoring {patients.length} patient{patients.length !== 1 ? 's' : ''}</p>
        </div>
      </div>
      <div className="patient-cards">
        {patients.map(p => (
          <div key={p._id} className="patient-card card">
            <div className="patient-card__header">
              <div className="patient-avatar">{p.name?.split(' ').map(n=>n[0]).join('').slice(0,2)}</div>
              <div>
                <h4>{p.name}</h4>
                <span className={`badge badge-${p.isActive ? 'success' : 'neutral'}`}>
                  {p.isActive ? 'Active' : 'Inactive'}
                </span>
              </div>
              {p.openAlerts > 0 && (
                <div className="patient-card__alerts">
                  <span>{p.openAlerts}</span>
                </div>
              )}
            </div>
            <div className="divider" />
            <div className="patient-card__stats">
              <div>
                <span className="stat-label">Last active</span>
                <span>{timeAgo(p.lastActive)}</span>
              </div>
              <div>
                <span className="stat-label">Mood</span>
                <span>{p.latestEmotion ? emotionIcon(p.latestEmotion.emotion) : '—'}</span>
              </div>
              <div>
                <span className="stat-label">Stage</span>
                <span style={{textTransform:'capitalize'}}>{p.diagnosisStage || '—'}</span>
              </div>
            </div>
          </div>
        ))}
        {patients.length === 0 && (
          <div className="empty-state card">
            <p>No patients assigned. Go to Patients to add one.</p>
          </div>
        )}
      </div>
    </div>
  );
}

/* ── Doctor Dashboard ────────────────────────────────────────── */
function DoctorDash() {
  const { data, loading } = useFetch(() => dashboardAPI.getDoctor(), []);
  if (loading) return <div className="page-loader"><div className="spinner" /></div>;

  const adherence = data?.overallMedicationAdherence30d;
  const doses     = data?.doseBreakdown30d || {};
  const alerts    = data?.alertBreakdown || {};

  return (
    <div className="dash anim-fade-up">
      <div className="page-header">
        <div className="page-header__left">
          <h1>Clinical overview</h1>
          <p>{data?.totalPatients || 0} patients under your care</p>
        </div>
      </div>

      <div className="dash-stats">
        <div className="stat-card">
          <span className="stat-label">Overall adherence (30d)</span>
          <span className="stat-value" style={{color: getAdherenceColor(adherence)}}>{adherence !== null ? `${adherence}%` : '—'}</span>
          <span className="stat-sub">Across all patients</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Doses taken (30d)</span>
          <span className="stat-value">{doses.taken || 0}</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Doses missed (30d)</span>
          <span className="stat-value" style={{color:'var(--danger)'}}>{doses.missed || 0}</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Missed med alerts</span>
          <span className="stat-value">{alerts.missed_medication || 0}</span>
        </div>
      </div>

      <div className="card" style={{marginTop:24}}>
        <h3 className="card-title" style={{marginBottom:16}}>Your patients</h3>
        <div className="table-wrap">
          <table>
            <thead>
              <tr><th>Patient</th><th>Diagnosis stage</th><th>Rx this month</th><th>Last active</th></tr>
            </thead>
            <tbody>
              {(data?.patients || []).map(p => (
                <tr key={p._id}>
                  <td><strong>{p.name}</strong><br/><span style={{color:'var(--ink-muted)',fontSize:12}}>{p.email}</span></td>
                  <td><span className="badge badge-info" style={{textTransform:'capitalize'}}>{p.diagnosisStage || '—'}</span></td>
                  <td>{p.prescriptionsThisMonth || 0}</td>
                  <td>{timeAgo(p.lastActive)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

function FamilyDashboard({ data: d, user }) {
  const greeting = () => {
    const h = new Date().getHours();
    if (h < 12) return 'Good morning';
    if (h < 17) return 'Good afternoon';
    return 'Good evening';
  };

  if (!d?.patient) return (
    <div className="empty-state card">
      <h3>No patient assigned yet</h3>
      <p>Ask the doctor to assign a patient to your account.</p>
    </div>
  );

  const doses   = d?.medications?.todaySummary || {};
  const emotion = d?.emotions?.latestFace;
  const sent    = d?.emotions?.sentimentLast7Days || {};

  return (
    <div className="anim-fade-up">
      <div className="page-header">
        <div className="page-header__left">
          <h1>{greeting()}, {user?.name?.split(' ')[0]}</h1>
          <p>Caring for {d?.patient?.name}</p>
        </div>
      </div>

      {/* Patient info card */}
      <div className="card" style={{ marginBottom: 20, display: 'flex', alignItems: 'center', gap: 16 }}>
        <div style={{
          width: 56, height: 56, borderRadius: '50%',
          background: 'var(--sage-light)', display: 'flex',
          alignItems: 'center', justifyContent: 'center',
          fontSize: 20, fontWeight: 500, color: 'var(--sage-dark)',
        }}>
          {d.patient.name?.split(' ').map(n => n[0]).join('').slice(0, 2)}
        </div>
        <div>
          <p style={{ fontWeight: 500, fontSize: 17 }}>{d.patient.name}</p>
          <p style={{ color: 'var(--ink-muted)', fontSize: 13 }}>
            Stage: {d.patient.diagnosisStage || 'Not set'} ·
            Last active: {d.patient.lastActive ? timeAgo(d.patient.lastActive) : 'Unknown'}
          </p>
        </div>
      </div>

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(150px,1fr))', gap: 16, marginBottom: 24 }}>
        <div className="stat-card">
          <span className="stat-label">Active medications</span>
          <span className="stat-value">{d?.medications?.activeCount || 0}</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Doses taken today</span>
          <span className="stat-value" style={{ color: 'var(--success)' }}>{doses.taken || 0}</span>
          <span className="stat-sub">of {doses.total || 0} scheduled</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Doses missed</span>
          <span className="stat-value" style={{ color: doses.missed > 0 ? 'var(--danger)' : 'inherit' }}>
            {doses.missed || 0}
          </span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Open alerts</span>
          <span className="stat-value" style={{ color: d?.alerts?.openCount > 0 ? 'var(--danger)' : 'inherit' }}>
            {d?.alerts?.openCount || 0}
          </span>
          <span className="stat-sub">{d?.alerts?.openCount > 0 ? 'Needs attention' : 'All clear'}</span>
        </div>
      </div>

      {/* Latest emotion */}
      {emotion && (
        <div className="card" style={{ marginBottom: 20 }}>
          <p style={{ fontSize: 12, fontWeight: 500, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--ink-muted)', marginBottom: 12 }}>
            Latest emotion detected
          </p>
          <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
            <span style={{ fontSize: 36 }}>{emotionIcon(emotion.emotion)}</span>
            <div>
              <p style={{ fontWeight: 500, fontSize: 17, textTransform: 'capitalize' }}>{emotion.emotion}</p>
              <p style={{ color: 'var(--ink-muted)', fontSize: 13 }}>
                {emotion.confidence?.toFixed(1)}% confidence · {timeAgo(emotion.recordedAt)}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Recent alerts */}
      {d?.alerts?.recent?.length > 0 && (
        <div className="card">
          <p style={{ fontSize: 12, fontWeight: 500, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--ink-muted)', marginBottom: 12 }}>
            Recent alerts
          </p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {d.alerts.recent.map((alert, i) => (
              <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 12, fontSize: 13 }}>
                <span style={{
                  width: 8, height: 8, borderRadius: '50%', flexShrink: 0,
                  background: alert.severity === 'critical' || alert.severity === 'high' ? 'var(--danger)' : 'var(--warn)',
                }} />
                <span style={{ flex: 1 }}>{alert.title}</span>
                <span style={{ color: 'var(--ink-muted)' }}>{timeAgo(alert.createdAt)}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

const greeting = () => {
  const h = new Date().getHours();
  if (h < 12) return 'morning';
  if (h < 17) return 'afternoon';
  return 'evening';
};
